using System;
using System.Collections.Generic;
using System.Linq;
using BepInEx.Configuration;
using EFT;
using EFT.SynchronizableObjects;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class TripwireHighlight {
 sealed record Entry(TripwireSynchronizableObject Item,int Id,Vector3 From,Vector3 To,Vector3 Grenade,float Distance,ETripwireState State);
 static ConfigEntry<bool> enabled=null!,throughWalls=null!;static ConfigEntry<float> range=null!,width=null!;static readonly List<Entry> entries=new();static IntPtr world;static float nextScan,nextError;static int mask;
 internal static void Initialize(){enabled=FeatureConfig.Bind("42. 绊雷高亮","Enabled","高亮绊雷与拉线",true,"标出本局已布设绊雷的拉线、端点和距离，拆除或爆炸后移除。");throughWalls=FeatureConfig.Bind("42. 绊雷高亮","Through walls","隔墙显示绊雷",true);range=FeatureConfig.Bind("42. 绊雷高亮","Range","绊雷高亮距离（米）",150f,"",new AcceptableValueRange<float>(0,500));width=FeatureConfig.Bind("42. 绊雷高亮","Line width","绊雷拉线宽度",3f,"",new AcceptableValueRange<float>(1,8));}
 internal static void Reset(){entries.Clear();world=IntPtr.Zero;nextScan=0;}
 static bool Dangerous(ETripwireState state)=>state is ETripwireState.Wait or ETripwireState.Active or ETripwireState.Exploding;
 static bool Finite(Vector3 p)=>float.IsFinite(p.x)&&float.IsFinite(p.y)&&float.IsFinite(p.z);
 static bool Live(Entry entry)=>entry.Item!=null&&entry.Item.ObjectId==entry.Id&&entry.Item.IsActive&&entry.Item.IsInited&&entry.Item.gameObject.activeInHierarchy&&Dangerous(entry.Item.TripwireState);
 internal static void Tick(GameWorld? current,Player? local){if(!enabled.Value||current==null||local==null||!RaidClock.Active){if(world!=IntPtr.Zero||entries.Count>0)Reset();return;}if(world!=current.Pointer){Reset();world=current.Pointer;}if(Time.unscaledTime<nextScan)return;nextScan=Time.unscaledTime+.25f;entries.Clear();try{var processor=current.SynchronizableObjectLogicProcessor;var list=processor?.TripwireManager?._tripwires;if(list==null)return;foreach(var wire in list){if(wire==null||!wire.IsActive||!wire.IsInited||!wire.gameObject.activeInHierarchy||!Dangerous(wire.TripwireState))continue;var from=wire._line?._fromPositionPivot??wire.FromPosition;var to=wire._line?._toPositionPivot??wire.ToPosition;if(!Finite(from)||!Finite(to)||(from-to).sqrMagnitude<.0001f)continue;var nearest=TripwireGeometry.Nearest(new(local.Position.x,local.Position.y,local.Position.z),new(from.x,from.y,from.z),new(to.x,to.y,to.z));float distance=System.Numerics.Vector3.Distance(new(local.Position.x,local.Position.y,local.Position.z),nearest);if(distance>range.Value)continue;var grenade=wire._grenadeComponent?.transform.position??wire._firstStakeWireEnd?.transform.position??from;entries.Add(new(wire,wire.ObjectId,from,to,grenade,distance,wire.TripwireState));}entries.Sort((a,b)=>a.Distance.CompareTo(b.Distance));}catch(Exception e){Warn(e);}}
 static bool Visible(Camera camera,Entry entry){if(throughWalls.Value)return true;if(mask==0)mask=LayerMask.GetMask("HighPolyCollider","Terrain","LowPolyCollider");if(mask==0)return false;var delta=(entry.From+entry.To)*.5f-camera.transform.position;return !Physics.Raycast(camera.transform.position,delta.normalized,Math.Max(0,delta.magnitude-.1f),mask,QueryTriggerInteraction.Ignore);}
 static void Segment(Camera camera,Vector3 a,Vector3 b,Color color,float thickness){var sa=camera.WorldToScreenPoint(a);var sb=camera.WorldToScreenPoint(b);if(!Finite(sa)||!Finite(sb))return;const float near=.05f;if(sa.z<near&&sb.z<near)return;if(sa.z<near){a=Vector3.Lerp(a,b,(near-sa.z)/(sb.z-sa.z));sa=camera.WorldToScreenPoint(a);}else if(sb.z<near){b=Vector3.Lerp(b,a,(near-sb.z)/(sa.z-sb.z));sb=camera.WorldToScreenPoint(b);}var from=new System.Numerics.Vector2(sa.x,Screen.height-sa.y);var to=new System.Numerics.Vector2(sb.x,Screen.height-sb.y);if(!TripwireGeometry.Clip(ref from,ref to,Screen.width,Screen.height))return;RaidLoot.Line(new(from.X,from.Y),new(to.X,to.Y),new Color(0,0,0,.85f),thickness+3);RaidLoot.Line(new(from.X,from.Y),new(to.X,to.Y),color,thickness);}
 static void Point(Camera camera,Vector3 point,Color color){var screen=camera.WorldToScreenPoint(point);if(screen.z<.05f||screen.x<0||screen.x>Screen.width||screen.y<0||screen.y>Screen.height)return;var p=new Vector2(screen.x,Screen.height-screen.y);const float size=6;RaidLoot.Line(p+new Vector2(-size,-size),p+new Vector2(size,-size),color,2);RaidLoot.Line(p+new Vector2(size,-size),p+new Vector2(size,size),color,2);RaidLoot.Line(p+new Vector2(size,size),p+new Vector2(-size,size),color,2);RaidLoot.Line(p+new Vector2(-size,size),p+new Vector2(-size,-size),color,2);}
 internal static void Draw(Camera camera){if(!enabled.Value||!RaidClock.Active||Event.current.type!=EventType.Repaint)return;try{int budget=128;foreach(var entry in entries){if(budget--<=0)break;if(!Live(entry)||!Visible(camera,entry))continue;var color=entry.Item.TripwireState==ETripwireState.Exploding?new Color(1,.15f,.1f):new Color(1,.32f,.75f);Segment(camera,entry.From,entry.To,color,width.Value);Point(camera,entry.From,color);Point(camera,entry.To,color);Point(camera,entry.Grenade,new Color(1,.8f,.2f));var mid=camera.WorldToScreenPoint((entry.From+entry.To)*.5f+Vector3.up*.18f);if(mid.z>.05f&&mid.x>=0&&mid.x<=Screen.width&&mid.y>=0&&mid.y<=Screen.height)InterfaceMenu.Label(new Rect(mid.x-160,Screen.height-mid.y-32,320,28),"绊雷 · "+(entry.Item.TripwireState==ETripwireState.Wait?"待激活":entry.Item.TripwireState==ETripwireState.Exploding?"已触发":"已布防")+" · "+entry.Distance.ToString("F0")+" 米",color,14);}}catch(Exception e){Warn(e);}}
 static void Warn(Exception e){if(Time.unscaledTime<nextError)return;nextError=Time.unscaledTime+20;Plugin.Self.Log.LogWarning("Tripwire highlight: "+e.Message);}
}
